const state={scenario:'studio',count:4,model:'Sharmax Atlas 1000 LX',generating:false};
const $=(s,r=document)=>r.querySelector(s);const $$=(s,r=document)=>[...r.querySelectorAll(s)];
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2700)}
function updateSummary(){const labels={studio:'каталог на белом фоне',details:'крупные узлы техники',nature:'техника в природе'};$('#generateSummary').textContent=state.count+' кадра · '+labels[state.scenario]}
function downloadText(filename,payload){const blob=new Blob([payload],{type:'application/json;charset=utf-8'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=filename;document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(link.href)}
$('#clearModel').addEventListener('click',()=>{$('#modelInput').value='';$('#modelInput').focus()});
$('#searchButton').addEventListener('click',()=>{const model=$('#modelInput').value.trim();if(!model){toast('Введите название модели или артикул.');$('#modelInput').focus();return}state.model=model;$('#sourceResult').innerHTML='<span class="pulse-dot"></span><strong>Модель сохранена:</strong> для поиска реальных фото нужно подключить источники и парсер.';toast('Модель «'+model+'» сохранена в проекте')});
$$('.source-filter').forEach(button=>button.addEventListener('click',()=>{$$('.source-filter').forEach(item=>item.classList.remove('selected'));button.classList.add('selected');toast('Фильтр источников: '+button.textContent.replace(/\\d+/g,'').trim())}));
$$('.reference-item').forEach(item=>item.addEventListener('click',()=>{$$('.reference-item').forEach(row=>row.classList.remove('selected'));item.classList.add('selected')}));
$$('.scenario-option').forEach(button=>button.addEventListener('click',()=>{$$('.scenario-option').forEach(item=>item.classList.remove('selected'));button.classList.add('selected');state.scenario=button.dataset.scenario;updateSummary()}));
function setCount(next){state.count=Math.max(4,Math.min(5,next));$('#sceneCount').textContent=state.count;updateSummary()}
$('#decreaseCount').addEventListener('click',()=>setCount(state.count-1));$('#increaseCount').addEventListener('click',()=>setCount(state.count+1));
$$('.angle-toggle input').forEach(input=>input.addEventListener('change',()=>input.closest('.angle-toggle').classList.toggle('checked',input.checked)));
$('#resetAngles').addEventListener('click',()=>{$$('.angle-toggle input').forEach(input=>{input.checked=true;input.closest('.angle-toggle').classList.add('checked')});toast('Все обязательные ракурсы восстановлены')});
$$('.switch').forEach(button=>button.addEventListener('click',()=>button.classList.toggle('on')));
$('#generateButton').addEventListener('click',()=>{const results=document.getElementById('projects');$('#resultStatus').textContent='Нет готовых фотографий';toast('Генератор пока не подключён — сайт не будет выдавать фальшивые изображения. Можно добавить реальные фото для просмотра.');results.scrollIntoView({behavior:'smooth',block:'start'})});
$$('.download-one').forEach(button=>button.addEventListener('click',()=>{const file=button.dataset.file;downloadText(file.replace('.webp','.json'),JSON.stringify({model:state.model,file,status:'preview',qualityGate:98,note:'Подключите image provider для получения бинарного изображения.'},null,2));toast('Метаданные '+file+' подготовлены для скачивания')}));
$('#downloadAll').addEventListener('click',()=>{downloadText(state.model.toLowerCase().replace(/[^a-z0-9а-я]+/gi,'-').replace(/-+/g,'-')+'-techshot-package.json',JSON.stringify({project:'TS-0248',model:state.model,output:'separate-files',scenario:state.scenario,count:state.count,qualityGate:{enabled:true,threshold:98,checks:['uncropped wheels','no artifacts','consistent model','preserved factory details']},files:['front-left.webp','side.webp','rear-right.webp','rear.webp']},null,2));toast('Архивный манифест скачан. В рабочем API он будет заменён ZIP с изображениями.')});
$('#copyEmbed').addEventListener('click',async()=>{const snippet='<iframe src="https://techshot-studio.mistacat.chatgpt.site/embed" data-profile="catalog-tech" data-output="separate-files" allow="downloads"></iframe>';try{await navigator.clipboard.writeText(snippet);toast('Код встраивания скопирован')}catch{toast('Выделите код вручную — браузер запретил доступ к буферу')}});
$$('[data-scroll]').forEach(button=>button.addEventListener('click',()=>{document.getElementById(button.dataset.scroll)?.scrollIntoView({behavior:'smooth',block:'start'});$$('.nav-item').forEach(item=>item.classList.remove('active'));button.classList.add('active')}));
updateSummary();
